mapper.select:
SELECT result_score
FROM game_max_result_data
WHERE game_mode = #{game_mode}
  AND game_level = #{game_level}
  AND user_uuid = #{user_uuid}

SELECT *
FROM in_game_wave
WHERE game_mode = #{game_mode}
  AND game_level = #{game_level}
ORDER by wave_num asc

SELECT game_mode, game_level, game_title, max_round, boss_point_reward, goods_spawn, exp_bonus, week_rank_1_reward, week_rank_2_reward, week_rank_3_reward
FROM game_mode_data
WHERE game_mode = #{game_mode}
  AND game_level = #{game_level}

SELECT COUNT(*) as boss_day_count
FROM game_start_data
WHERE user_uuid = #{user_uuid}
  and game_mode = #{game_mode}
  AND game_level = #{game_level}
  AND DATE(ins_date) = CURDATE()
